   580  static uint8_t filters_to_flags(const uint8_t* filters) {
   581    uint8_t flags = 0;
   582
   583    for (int i = 0; i < BLOSC2_MAX_FILTERS; i++) {
   584      switch (filters[i]) {
   585        case BLOSC_SHUFFLE:
