  2978  /* execute single compression/decompression job for a single thread_context */
  2979  static void t_blosc_do_job(void *ctxt)
  2980  {
  2981    struct thread_context* thcontext = (struct thread_context*)ctxt;
  2982    blosc2_context* context = thcontext->parent_context;
  2983    int32_t cbytes;
  2984    int32_t ntdest;
  2985    int32_t tblocks;               /* number of blocks per thread */
  2986    int32_t tblock;                /* limit block on a thread */
  2987    int32_t nblock_;              /* private copy of nblock */
  2988    int32_t bsize;
  2989    int32_t leftoverblock;
  2990    /* Parameters for threads */
  2991    int32_t blocksize;
  2992    int32_t ebsize;
  2993    int32_t srcsize;
  2994    bool compress = context->do_compress != 0;
  2995    int32_t maxbytes;
  2996    int32_t nblocks;
  2997    int32_t leftover;
  2998    int32_t leftover2;
  2999    int32_t* bstarts;
  3000    const uint8_t* src;
  3001    uint8_t* dest;
  3002    uint8_t* tmp;
  3003    uint8_t* tmp2;
  3004    uint8_t* tmp3;
  3005
  3006    /* Get parameters for this thread before entering the main loop */
  3007    blocksize = context->blocksize;
  3008    ebsize = blocksize + context->typesize * (int32_t)sizeof(int32_t);
  3009    maxbytes = context->destsize;
  3010    nblocks = context->nblocks;
  3011    leftover = context->leftover;
  3012    bstarts = context->bstarts;
  3013    src = context->src;
  3014    srcsize = context->srcsize;
  3015    dest = context->dest;
  3016
  3017    /* Resize the temporaries if needed */
  3018    if (blocksize > thcontext->tmp_blocksize) {
  3019      my_free(thcontext->tmp);
  3020      thcontext->tmp_nbytes = (size_t) 4 * ebsize;
  3021      thcontext->tmp = my_malloc(thcontext->tmp_nbytes);
  3022      thcontext->tmp2 = thcontext->tmp + ebsize;
  3023      thcontext->tmp3 = thcontext->tmp2 + ebsize;
  3024      thcontext->tmp4 = thcontext->tmp3 + ebsize;
  3025      thcontext->tmp_blocksize = blocksize;
  3026    }
  3027
  3028    tmp = thcontext->tmp;
  3029    tmp2 = thcontext->tmp2;
  3030    tmp3 = thcontext->tmp3;
  3031
  3032    // Determine whether we can do a static distribution of workload among different threads
  3033    bool memcpyed = context->header_flags & (uint8_t)BLOSC_MEMCPYED;
  3034    if (!context->do_compress && context->special_type) {
  3035      // Fake a runlen as if its a memcpyed chunk
  3036      memcpyed = true;
  3037    }
  3038
  3039    bool static_schedule = (!compress || memcpyed) && context->block_maskout == NULL;
  3040    if (static_schedule) {
  3041        /* Blocks per thread */
  3042        tblocks = nblocks / context->nthreads;
  3043        leftover2 = nblocks % context->nthreads;
  3044        tblocks = (leftover2 > 0) ? tblocks + 1 : tblocks;
  3045        nblock_ = thcontext->tid * tblocks;
  3046        tblock = nblock_ + tblocks;
  3047        if (tblock > nblocks) {
  3048            tblock = nblocks;
  3049        }
  3050    }
  3051    else {
  3052      // Use dynamic schedule via a queue.  Get the next block.
  3053      pthread_mutex_lock(&context->count_mutex);
  3054      context->thread_nblock++;
  3055      nblock_ = context->thread_nblock;
  3056      pthread_mutex_unlock(&context->count_mutex);
  3057      tblock = nblocks;
  3058    }
  3059
  3060    /* Loop over blocks */
  3061    leftoverblock = 0;
  3062    while ((nblock_ < tblock) && (context->thread_giveup_code > 0)) {
  3063      bsize = blocksize;
  3064      if (nblock_ == (nblocks - 1) && (leftover > 0)) {
  3065        bsize = leftover;
  3066        leftoverblock = 1;
  3067      }
  3068      if (compress) {
  3069        if (memcpyed) {
  3070          if (!context->prefilter) {
  3071            /* We want to memcpy only */
  3072            memcpy(dest + context->header_overhead + nblock_ * blocksize,
  3073                   src + nblock_ * blocksize, (unsigned int) bsize);
  3074            cbytes = (int32_t) bsize;
  3075          }
