    16  /* Whether a codec is meant for High Compression Ratios
    17     Includes LZ4 + BITSHUFFLE here, but not BloscLZ + BITSHUFFLE because,
    18     for some reason, the latter does not work too well */
    19  static bool is_HCR(blosc2_context * context) {
    20    switch (context->compcode) {
    21      case BLOSC_BLOSCLZ :
    22        return false;
    23      case BLOSC_LZ4 :
    24        return (context->filter_flags & BLOSC_DOBITSHUFFLE) ? true : false;
    25      case BLOSC_LZ4HC :
    26      case BLOSC_ZLIB :
    27      case BLOSC_ZSTD :
    28        return true;
    29      default :
    30        return false;
    31    }
    32  }
