    40  // Set the automatic blocksize 0 to its real value
    41  void blosc_stune_next_blocksize(blosc2_context *context) {
    42    int32_t clevel = context->clevel;
    43    int32_t typesize = context->typesize;
    44    int32_t nbytes = context->sourcesize;
    45    int32_t user_blocksize = context->blocksize;
    46    int32_t blocksize = nbytes;
    47
    48    // Protection against very small buffers
    49    if (nbytes < typesize) {
    50      context->blocksize = 1;
    51      return;
    52    }
    53
    54    if (user_blocksize) {
    55      blocksize = user_blocksize;
    56      goto last;
    57    }
    58
    59    if (nbytes >= L1) {
    60      blocksize = L1;
    61
    62      /* For HCR codecs, increase the block sizes by a factor of 2 because they
    63          are meant for compressing large blocks (i.e. they show a big overhead
    64          when compressing small ones). */
    65      if (is_HCR(context)) {
    66        blocksize *= 2;
    67      }
    68
    69      // Choose a different blocksize depending on the compression level
    70      switch (clevel) {
    71        case 0:
    72          // Case of plain copy
    73          blocksize /= 4;
    74          break;
    75        case 1:
    76          blocksize /= 2;
    77          break;
    78        case 2:
    79          blocksize *= 1;
    80          break;
    81        case 3:
    82          blocksize *= 2;
    83          break;
    84        case 4:
    85        case 5:
    86          blocksize *= 4;
    87          break;
    88        case 6:
    89        case 7:
    90        case 8:
    91          blocksize *= 8;
    92          break;
    93        case 9:
    94          // Do not exceed 256 KB for non HCR codecs
    95          blocksize *= 8;
    96          if (is_HCR(context)) {
    97            blocksize *= 2;
    98          }
    99          break;
   100        default:
   101          break;
   102      }
   103    }
   104
   105    /* Now the blocksize for splittable codecs */
   106    if (clevel > 0 && split_block(context, typesize, blocksize)) {
   107      // For performance reasons, do not exceed 256 KB (it must fit in L2 cache)
   108      switch (clevel) {
   109        case 1:
   110        case 2:
   111        case 3:
   112          blocksize = 32 * 1024;
   113          break;
   114        case 4:
   115        case 5:
   116        case 6:
   117        case 7:
   118        case 8:
   119          blocksize = 256 * 1024;
   120          break;
   121        case 9:
   122        default:
   123          blocksize = 512 * 1024;
   124          break;
   125      }
   126      // Multiply by typesize to get proper split sizes
   127      blocksize *= typesize;
   128      // But do not exceed 4 MB per thread (having this capacity in L3 is normal in modern CPUs)
   129      if (blocksize > 4 * 1024 * 1024) {
   130        blocksize = 4 * 1024 * 1024;
   131      }
   132      if (blocksize < 32 * 1024) {
   133        /* Do not use a too small blocksize (< 32 KB) when typesize is small */
   134        blocksize = 32 * 1024;
   135      }
   136    }
   137
   138    last:
   139    /* Check that blocksize is not too large */
   140    if (blocksize > nbytes) {
   141      blocksize = nbytes;
   142    }
   143
   144    // blocksize *must absolutely* be a multiple of the typesize
   145    if (blocksize > typesize) {
   146      blocksize = blocksize / typesize * typesize;
   147    }
   148
   149    context->blocksize = blocksize;
   150  }
