   165  int split_block(blosc2_context *context, int32_t typesize, int32_t blocksize) {
   166    switch (context->splitmode) {
   167      case BLOSC_ALWAYS_SPLIT:
   168        return 1;
   169      case BLOSC_NEVER_SPLIT:
   170        return 0;
   171      case BLOSC_FORWARD_COMPAT_SPLIT:
   172      case BLOSC_AUTO_SPLIT:
   173        // These cases will be handled later
   174        break;
   175      default:
   176        BLOSC_TRACE_WARNING("Unrecognized split mode.  Default to BLOSC_FORWARD_COMPAT_SPLIT");
   177    }
   178
   179    int compcode = context->compcode;
   180    return (
   181            // Fast codecs like blosclz and lz4 always prefer to always split
   182            ((compcode == BLOSC_BLOSCLZ) || (compcode == BLOSC_LZ4)) &&
   183            (typesize <= MAX_STREAMS) &&
   184            (blocksize / typesize) >= BLOSC_MIN_BUFFERSIZE);
   185  }
